import{_ as a,o as e,a as d,b as r}from"./app.DKoEZOcr.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_matrix_operator/intermediate_optimization.md","filePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_matrix_operator/intermediate_optimization.md","outlineHeaders":[{"level":2,"title":"优化路径：","slug":"优化路径：","link":"#优化路径："},{"level":2,"title":"从入门到优化","slug":"从入门到优化","link":"#从入门到优化"},{"level":2,"title":"详细内容","slug":"详细内容","link":"#详细内容"}],"lastUpdated":1786954352000}'),o={name:"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_matrix_operator/intermediate_optimization.md"};function i(s,t,_,c,p,m){return e(),d("div",null,[...t[0]||(t[0]=[r('<div><article class="markdown-body"><h1>中级性能优化</h1><p>本节基于C++ Tensor编程范式，介绍Matmul基础API算子的性能调优方法，通过4个渐进式优化步骤（L1/L0双缓冲机制、细粒度流水同步、多核并行切分、DataCopyIn优先搬运B矩阵），展示从基础实现到高性能优化的完整调优路径。</p><h2 id="优化路径：">优化路径：<a class="header-anchor" href="#优化路径：">​</a></h2><table><thead><tr><th>编号</th><th>优化手段</th><th>等级</th><th>定位</th></tr></thead><tbody><tr><td><strong>1</strong></td><td><strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#1-l1l0-%E5%8F%8C%E7%BC%93%E5%86%B2-ping-pong-%E5%B8%83%E5%B1%80">L1/L0双缓冲Ping-Pong布局</a></strong></td><td><strong>中级</strong></td><td><strong>流水线骨架</strong></td></tr><tr><td><strong>2</strong></td><td><strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#2-%E7%BB%86%E7%B2%92%E5%BA%A6%E6%B5%81%E6%B0%B4%E5%90%8C%E6%AD%A5">细粒度流水同步</a></strong></td><td><strong>中级</strong></td><td><strong>流水线骨架</strong></td></tr><tr><td><strong>3</strong></td><td><strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#3-%E5%A4%9A%E6%A0%B8%E5%B9%B6%E8%A1%8C%E5%88%87%E5%88%86">多核并行切分</a></strong></td><td><strong>中级</strong></td><td><strong>并行策略</strong></td></tr><tr><td><strong>4</strong></td><td><strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#4-datacopyin-%E4%BC%98%E5%85%88%E6%90%AC%E8%BF%90-b-%E7%9F%A9%E9%98%B5">DataCopyIn优先搬运B矩阵</a></strong></td><td><strong>中级</strong></td><td><strong>调度策略</strong></td></tr><tr><td>5</td><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#5-%E5%A4%A7%E5%8C%85%E6%90%AC%E8%BF%90">大包搬运</a></td><td>高级</td><td>流水线骨架</td></tr><tr><td>6</td><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#6-loaddata3d-%E6%9B%BF%E4%BB%A3-loaddata2d%E5%87%8F%E5%B0%91%E6%8C%87%E4%BB%A4%E9%98%9F%E5%88%97%E5%8D%A0%E7%94%A8">LoadData3D替代LoadData2D</a></td><td>高级</td><td>指令队列优化</td></tr><tr><td>7</td><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#7-%E5%B8%B8%E9%87%8F-tiling">常量Tiling</a></td><td>高级</td><td>编译期优化</td></tr><tr><td>8</td><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#8-unitflag-%E4%BC%98%E5%8C%96">UnitFlag优化</a></td><td>高级</td><td>MMAD-FIXPIPE流水重叠</td></tr><tr><td>9</td><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#9-l2cache-%E4%BC%98%E5%8C%96">L2Cache优化</a></td><td>高级</td><td>MTE2带宽压榨</td></tr></tbody></table><h2 id="从入门到优化">从入门到优化<a class="header-anchor" href="#从入门到优化">​</a></h2><p><a href="./getting_started.html">入门功能落地</a>实现了Matmul算子的基本功能：A/B 矩阵经 MTE2 的 <code>DataCopy</code> 从GM搬入L1（ND→NZ转换），经MTE1的 <code>LoadData</code> 搬入L0A/L0B（NZ→ZZ/ZN 转换），Cube单元执行 <code>Mmad</code>，结果经 <code>Fixpipe</code> 从L0C写回GM。</p><p>入门实现存在以下<strong>性能瓶颈</strong>——这也是中级优化的起点：</p><table><thead><tr><th>瓶颈</th><th>入门实现的问题</th><th>对应的中级优化</th></tr></thead><tbody><tr><td><strong>L1/L0 单缓冲区</strong></td><td>A、B矩阵在L1和L0中各只有一份缓冲区，下一轮数据必须等上一轮消费完才能搬入</td><td>改为Ping-Pong双缓冲，让数据搬运和计算重叠执行</td></tr><tr><td><strong>流水线串行执行</strong></td><td>当前实现中使用PipeBarrier和SetFlag/WaitFlag进行流水线同步，但未采用双缓冲机制，MTE2、MTE1、M、FIX各硬件单元无法充分流水并行</td><td>通过双缓冲和硬件事件同步，使四个单元流水并行，显著提升吞吐</td></tr><tr><td><strong>多核切分固定</strong></td><td>硬编码 <code>M / singleCoreM</code> 计算核数分配，仅适用于固定矩阵规模和核数场景</td><td>通用切分策略，支撑任意核数和矩阵规模的自动分配</td></tr><tr><td><strong>B矩阵搬运等待</strong></td><td>A和B依次搬运，B数据到位晚导致L1缓冲区欠载</td><td>优先搬B → 先B后 调度</td></tr><tr><td>MTE2单条搬运指令粒度小</td><td>DataCopyIn每次搬入一个 <code>baseM×baseK</code> 块，MTE2指令发射次数多</td><td>大包搬运 → 一次搬入 <code>stepKa</code> 个block</td></tr><tr><td>MTE1指令队列压力大</td><td>LoadData2D一次只能搬一个16×K切片，需for循环多次发射</td><td>LoadData3D → 单条指令完成搬运</td></tr><tr><td>Tiling参数运行时计算</td><td>所有参数在kernel内用Scalar计算，增加流水线停顿</td><td>常量Tiling → 编译期确定</td></tr><tr><td>L0C写回阻塞</td><td><code>Fixpipe</code> 与Mmad串行，Cube 等待写回完成再计算</td><td>UnitFlag → 512B粒度MMAD-FIXPIPE重叠</td></tr><tr><td>L2Cache未充分利用</td><td>当前实现中B矩阵每次均从GM读取，多核反复访问GM导致MTE2带宽压力大；L2Cache纯读带宽约3~4倍于GM，但当前实现未能利用这一特性</td><td>沿M方向切分A矩阵，使B矩阵跨轮驻留L2Cache，减少GM访问次数，有效降低MTE2耗时</td></tr></tbody></table><h2 id="详细内容">详细内容<a class="header-anchor" href="#详细内容">​</a></h2><p>详细内容请参考 <a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance">Matmul 基础API最佳实践样例</a>，其中涵盖中级性能优化的4个核心步骤：</p><ul><li>1、<strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#1-l1l0-%E5%8F%8C%E7%BC%93%E5%86%B2-ping-pong-%E5%B8%83%E5%B1%80">L1/L0 双缓冲 Ping-Pong 布局</a></strong>：DataCopyIn（GM→L1）、DataLoad（L1→L0）与Compute三个阶段形成三级流水</li><li>2、<strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#2-%E7%BB%86%E7%B2%92%E5%BA%A6%E6%B5%81%E6%B0%B4%E5%90%8C%E6%AD%A5">细粒度流水同步</a></strong>：四类硬件事件（MTE2_MTE1、MTE1_MTE2、MTE1_M、M_MTE1）精确控制流水线</li><li>3、<strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#3-%E5%A4%9A%E6%A0%B8%E5%B9%B6%E8%A1%8C%E5%88%87%E5%88%86">多核并行切分</a></strong>：M/N方向均匀切分，支撑任意核数和矩阵规模的自动分配</li><li>4、<strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#4-datacopyin-%E4%BC%98%E5%85%88%E6%90%AC%E8%BF%90-b-%E7%9F%A9%E9%98%B5">DataCopyIn 优先搬运 B 矩阵</a></strong>：先B后A调度，缓解L1缓冲区欠载</li></ul><p>每步优化均包含原理说明与数据流向说明，并附有功能调试（printf、DumpTensor）与性能调试（msOpProf）方法说明。</p><blockquote><p><strong>说明</strong>：该样例中L2Cache切分的性能分析属于高级极限打磨内容，其具体实现原理与性能数据请参考<a href="./advanced_extreme_optimization.html">高级极限打磨</a>，不在本中级性能优化文档中展开。</p></blockquote></article></div>',1)])])}const E=a(o,[["render",i]]);export{l as __pageData,E as default};
